/**
 * {@link HashJoinBindingContract#from} can claim a lookup attribute is assured although a row leaves it unbound (an
 * Extension whose expression errors keeps the variable in the assured set; a silent SERVICE that fails produces no
 * binding). The hash join must stay correct anyway: build rows that miss a lookup attribute go to partial-key indexes,
 * and probe rows that miss one are checked against every build row by compatibility. The same holds when the build side
 * outgrows its memory budget and is joined from the spill file.
 */
class HashJoinPartialLookupKeyTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@AfterEach
	void clearBudget() {
		System.clearProperty(HashJoinIteration.MAX_BUILD_ROWS_PROPERTY);
	}

	@ParameterizedTest(name = "extraRightRows={0}, maxBuildRows={1}")
	@CsvSource({ "0, -1", "3, -1", "3, 1" })
	void extensionOverwriteClearingOneOfTwoLookupKeysKeepsCompatibleRows(int extraRightRows, long maxBuildRows)
			throws Exception {
		List<Statement> data = new ArrayList<>(List.of(
				st("l", "l1", "v1"), st("l", "l2", "w1"),
				st("r", "r1", "v1"), st("r", "r2", "w1"),
				st("r2", "r1", "v2"), st("r2", "r2", "w2")));
		for (int i = 0; i < extraRightRows; i++) {
			data.add(st("rx" + i, "r1", "vx" + i));
			data.add(st("rx" + i, "r2", "wx" + i));
		}
		TupleExpr left = new Extension(new Join(pattern("l", "l1", "x"), pattern("l", "l2", "y")),
				new ExtensionElem(new Str(Var.of("missing")), "x"));
		TupleExpr right = new Difference(new Join(pattern("r", "r1", "x"), pattern("r", "r2", "y")),
				new SingletonSet());
		Join join = new Join(left, right);
		QueryRoot root = new QueryRoot(join);

		HashJoinBindingContract contract = HashJoinBindingContract.from(left, right);
		assertThat(contract.lookupBindings()).as("x is over-claimed as assured on the Extension side")
				.containsExactly("x", "y");

		System.setProperty(HashJoinIteration.MAX_BUILD_ROWS_PROPERTY, Long.toString(maxBuildRows));
		assertThat(rows(evaluate(root, new ListTripleSource(data), null)))
				.containsExactly("{l=urn:ex:l, r=urn:ex:r, x=urn:ex:v1, y=urn:ex:w1}");
		assertThat(join.getAlgorithmName()).isEqualTo(HashJoinIteration.class.getSimpleName());
	}

	@ParameterizedTest(name = "maxBuildRows={0}")
	@ValueSource(longs = { -1L, 1L })
	void extensionOverwriteOnProbeSideWithTwoKeysKeepsCompatibleRows(long maxBuildRows) throws Exception {
		List<Statement> data = new ArrayList<>(List.of(
				st("l", "l1", "v1"), st("l", "l2", "w1"),
				st("r", "r1", "v1"), st("r", "r2", "w1")));
		for (int i = 0; i < 4; i++) {
			data.add(st("l" + i, "l1", "vx" + i));
			data.add(st("l" + i, "l2", "w1"));
		}
		for (int i = 0; i < 3; i++) {
			// right rows no left row is compatible with; with a budget of one both inputs exceed it
			data.add(st("rx" + i, "r1", "rv" + i));
			data.add(st("rx" + i, "r2", "rw" + i));
		}
		TupleExpr left = new Extension(new Join(pattern("l", "l1", "x"), pattern("l", "l2", "y")),
				new ExtensionElem(new Str(Var.of("missing")), "x"));
		TupleExpr right = new Difference(new Join(pattern("r", "r1", "x"), pattern("r", "r2", "y")),
				new SingletonSet());
		Join join = new Join(left, right);
		QueryRoot root = new QueryRoot(join);

		System.setProperty(HashJoinIteration.MAX_BUILD_ROWS_PROPERTY, Long.toString(maxBuildRows));
		// every left row loses x and is compatible with the single right row that has y = w1
		assertThat(rows(evaluate(root, new ListTripleSource(data), null))).hasSize(5)
				.allMatch(row -> row.contains("r=urn:ex:r,") && row.contains("y=urn:ex:w1"));
		assertThat(join.getAlgorithmName()).isEqualTo(HashJoinIteration.class.getSimpleName());
	}

	@ParameterizedTest(name = "maxBuildRows={0}")
	@ValueSource(longs = { -1L, 1L })
	void silentServiceFailureOverClaimsAssuredButHashJoinStaysCorrect(long maxBuildRows) throws Exception {
		List<Statement> data = List.of(st("l", "l1", "v1"), st("l", "l2", "w1"), st("l2", "l1", "v2"),
				st("l2", "l2", "w2"), st("r2", "r2", "w1"), st("r3", "r2", "w3"));
		TupleExpr left = new Join(pattern("l", "l1", "x"), pattern("l", "l2", "y"));
		Service service = new Service(constant("_const_svc", iri("svc")), pattern("r", "r1", "x"), "?r <urn:ex:r1> ?x",
				Map.of(), null, true);
		TupleExpr right = new Difference(new Join(service, pattern("r2", "r2", "y")), new SingletonSet());
		Join join = new Join(left, right);
		QueryRoot root = new QueryRoot(join);
		FederatedServiceResolver failing = serviceUrl -> {
			throw new QueryEvaluationException("service unavailable");
		};
		assertThat(HashJoinBindingContract.from(left, right).lookupBindings())
				.as("SERVICE SILENT body variables are claimed assured")
				.contains("x", "y");

		System.setProperty(HashJoinIteration.MAX_BUILD_ROWS_PROPERTY, Long.toString(maxBuildRows));
		assertThat(rows(evaluate(root, new ListTripleSource(data), failing)))
				.containsExactly("{l=urn:ex:l, r2=urn:ex:r2, x=urn:ex:v1, y=urn:ex:w1}");
		assertThat(join.getAlgorithmName()).isEqualTo(HashJoinIteration.class.getSimpleName());
	}

	private static IRI iri(String local) {
		return VF.createIRI("urn:ex:" + local);
	}

	private static Var constant(String name, Value value) {
		return Var.of(name, value, false, true);
	}

	private static StatementPattern pattern(String subject, String predicate, String object) {
		return new StatementPattern(Var.of(subject), constant("_const_" + predicate, iri(predicate)), Var.of(object));
	}

	private static Statement st(String s, String p, String o) {
		return VF.createStatement(iri(s), iri(p), iri(o));
	}

	private static List<String> rows(List<BindingSet> bindingSets) {
		List<String> rows = new ArrayList<>();
		for (BindingSet bindingSet : bindingSets) {
			TreeMap<String, String> sorted = new TreeMap<>();
			for (String name : bindingSet.getBindingNames()) {
				Value value = bindingSet.getValue(name);
				if (value != null) {
					sorted.put(name, value.stringValue());
				}
			}
			rows.add(sorted.toString());
		}
		rows.sort(Comparator.naturalOrder());
		return rows;
	}

	private static List<BindingSet> evaluate(TupleExpr expression, TripleSource source,
			FederatedServiceResolver resolver) {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, resolver);
		List<BindingSet> results = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.evaluate(expression,
				EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				results.add(iteration.next());
			}
		}
		return results;
	}

	private static final class ListTripleSource implements TripleSource {
		private final List<Statement> statements;

		private ListTripleSource(List<Statement> statements) {
			this.statements = statements;
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws QueryEvaluationException {
			return new CloseableIteratorIteration<>(statements.stream()
					.filter(statement -> subj == null || subj.equals(statement.getSubject()))
					.filter(statement -> pred == null || pred.equals(statement.getPredicate()))
					.filter(statement -> obj == null || obj.equals(statement.getObject()))
					.iterator());
		}

		@Override
		public Set<StatementOrder> getSupportedOrders(Resource subj, IRI pred, Value obj, Resource... contexts)
				throws QueryEvaluationException {
			return Set.of();
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}

		@Override
		public Comparator<Value> getComparator() {
			return null;
		}
	}
}
